const line=d3.line().x(d=>x(d.day)).y(d=>y(convert(d.value))).curve(d3.curveMonotoneX);for(const l of src.lines){const values=l.values.slice(src.start).map((v,i)=>({day:src.start+i,value:v}));if(l.key==='composite'){const area=d3.area().x(d=>x(d.day)).y0(h-p.b).y1(d=>y(convert(d.value))).curve(d3.curveMonotoneX);svg.append('path').attr('d',area(values)).attr('fill','var(--h-accent)').attr('opacity',.075)}svg.append('path').attr('d',line(values)).attr('fill','none').attr('stroke',l.color).attr('stroke-width',l.key==='reference'?1.2:2.15).attr('stroke-dasharray',l.key==='reference'?'2 5':null).attr('stroke-linecap','round')}
if(src.forecast&&src.lines.some(l=>l.key==='composite')){const area=d3.area().x(d=>x(d.day)).y0(d=>y(convert(d.lo))).y1(d=>y(convert(d.hi))).curve(d3.curveMonotoneX);svg.append('path').attr('d',area(src.scenario)).attr('fill','var(--h-accent)').attr('opacity',.13);svg.append('path').attr('d',line(src.scenario.map(s=>({day:s.day,value:s.mid})))).attr('fill','none').attr('stroke','var(--h-accent)').attr('stroke-width',1.6).attr('stroke-dasharray','5 4');svg.append('line').attr('x1',x(94)).attr('x2',x(94)).attr('y1',p.t).attr('y2',h-p.b).attr('stroke','var(--h-line)').attr('stroke-dasharray','2 4')}
